#!/bin/bash
sed -i 's/import androidx.compose.foundation.gestures.detectDragGestures/import androidx.compose.foundation.gestures.detectDragGestures\nimport androidx.compose.foundation.draganddrop.dragAndDropSource\nimport androidx.compose.ui.draganddrop.DragAndDropTransferData\nimport android.content.ClipDescription\nimport android.view.View\nimport android.net.Uri\nimport android.webkit.MimeTypeMap/g' /app/applet/app/src/main/java/com/example/overlay/RadialMenuOverlay.kt

sed -i 's/TextButton(/val isUri = item.text.startsWith("content:\/\/") || item.text.startsWith("file:\/\/")\n                    val clipDataDrag = if (isUri) {\n                        val uri = Uri.parse(item.text)\n                        val mimeType = context.contentResolver.getType(uri) ?: MimeTypeMap.getSingleton().getMimeTypeFromExtension(MimeTypeMap.getFileExtensionFromUrl(item.text)) ?: "*\/*"\n                        \/\/ FileProvider Comment: Ensure any local files dragged from the HUD are exposed via a FileProvider (content:\/\/ URI). Passing raw file:\/\/ URIs will cause a FileUriExposedException crash.\n                        ClipData(ClipDescription("Dragged File", arrayOf(mimeType)), ClipData.Item(uri))\n                    } else {\n                        ClipData.newPlainText("Clipboard history", item.text)\n                    }\n                    \n                    TextButton(\n                        modifier = Modifier.dragAndDropSource {\n                            detectTapGestures(onLongPress = {\n                                startTransfer(\n                                    DragAndDropTransferData(\n                                        clipData = clipDataDrag,\n                                        flags = View.DRAG_FLAG_GLOBAL or View.DRAG_FLAG_GLOBAL_URI_READ\n                                    )\n                                )\n                            })\n                        },/g' /app/applet/app/src/main/java/com/example/overlay/RadialMenuOverlay.kt
